// scripts/generate-sw.js
// This script generates the firebase-messaging-sw.js file with environment variables

const fs = require('fs');
const path = require('path');
const firebaseVersion = require('firebase/package.json').version;

// Service worker template
function renderServiceWorker(firebaseConfig) {
return `// firebase-messaging-sw.js
// AUTO-GENERATED - DO NOT EDIT MANUALLY
// Generated by scripts/generate-sw.js

importScripts('https://www.gstatic.com/firebasejs/${firebaseVersion}/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/${firebaseVersion}/firebase-messaging-compat.js');

// Firebase configuration (injected at build time)
const firebaseConfig = ${JSON.stringify(firebaseConfig, null, 2)};

// Skip initialization if config is not set
let messaging = null;
if (!firebaseConfig.apiKey) {
  console.warn('[firebase-messaging-sw.js] Firebase config not set. Push notifications will not work.');
} else {
  // Initialize Firebase
  firebase.initializeApp(firebaseConfig);
  // Initialize Firebase Messaging
  messaging = firebase.messaging();
}

// Handle background messages
if (messaging) {
  messaging.onBackgroundMessage((payload) => {

    const notificationTitle = payload.notification?.title || 'New Notification';
    const notificationOptions = {
      body: payload.notification?.body || '',
      icon: '/favicon.ico',
      badge: '/favicon.ico',
      data: payload.data,
      tag: payload.data?.notification_id || Date.now().toString(),
      requireInteraction: payload.data?.priority === 'urgent',
      actions: payload.data?.action_url ? [
        {
          action: 'open',
          title: 'View'
        },
        {
          action: 'close',
          title: 'Dismiss'
        }
      ] : []
    };

    return self.registration.showNotification(notificationTitle, notificationOptions);
  });
}

// Handle notification clicks
self.addEventListener('notificationclick', (event) => {

  event.notification.close();

  // Handle action buttons
  if (event.action === 'open' || !event.action) {
    let urlToOpen = self.location.origin + '/';
    try {
      const target = new URL(event.notification.data?.action_url || '/', self.location.origin);
      if (target.origin === self.location.origin && ['https:', 'http:'].includes(target.protocol)) {
        urlToOpen = target.href;
      }
    } catch { /* Invalid links fall back to the app, never an external origin. */ }

    event.waitUntil(
      clients.matchAll({ type: 'window', includeUncontrolled: true })
        .then((windowClients) => {
          // Check if there's already a window open
          for (let i = 0; i < windowClients.length; i++) {
            const client = windowClients[i];
            if (client.url === urlToOpen && 'focus' in client) {
              return client.focus();
            }
          }

          // Open new window if none found
          if (clients.openWindow) {
            return clients.openWindow(urlToOpen);
          }
        })
    );
  }
});
`;
}

module.exports = { renderServiceWorker };
if (require.main === module) {
  import('vite').then(({ loadEnv }) => {
    const env = loadEnv(process.argv[2] || 'development', path.join(__dirname, '..'), 'REACT_APP_');
    const config = {
      apiKey: env.REACT_APP_FIREBASE_API_KEY || '',
      authDomain: env.REACT_APP_FIREBASE_AUTH_DOMAIN || '',
      projectId: env.REACT_APP_FIREBASE_PROJECT_ID || '',
      storageBucket: env.REACT_APP_FIREBASE_STORAGE_BUCKET || '',
      messagingSenderId: env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID || '',
      appId: env.REACT_APP_FIREBASE_APP_ID || '',
    };
    fs.writeFileSync(path.join(__dirname, '../public/firebase-messaging-sw.js'), renderServiceWorker(config));
    console.log('Generated Firebase service worker with public configuration');
  }).catch(error => { console.error(error); process.exitCode = 1; });
}
